import React from 'react';
import Limage from "../assets/im.jpeg"
import Navbar from '../components/Navbar';
import { Link } from 'react-router-dom';

export default function Landing() {
  React.useEffect(() => {
    // Reset any global styles (kept - safe)
    document.body.style.margin = '0';
    document.body.style.padding = '0';
    // keep background color fallback — visual replaced by component background but keep safe value
    document.body.style.backgroundColor = '#402E2A';

    const currentPath = window.location.pathname;
    if (currentPath === '/' || currentPath === '/landing') {
      const justLoggedOut = sessionStorage.getItem('justLoggedOut');
      if (justLoggedOut) {
        sessionStorage.removeItem('justLoggedOut');
      }
    }
  }, []);

  // Inline styles remain but updated to the new theme
  const styles = {
    body: {
      fontFamily: "'Lora', serif",
      // Use transparent so our component-level gradient can show through
      backgroundColor: 'transparent',
      color: '#3b2f2f',
      lineHeight: '1.6',
      padding: 0,
      width: '100%',
      maxWidth: '2560px',
      overflowX: 'hidden',

      position: 'relative',
    },


    // Top-level container that adds the gradient and safe padding
    pageWrap: {
      minHeight: '100vh',
      background: 'radial-gradient(circle at 10% 10%, #f5e9df 0%, #e6d5c3 10%, #caaea0 30%, #947C70 55%, #5b3f36 85%, #3b2f2f 100%)',
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'stretch',
      position: 'relative',
      zIndex: 0,
    },

    // subtle grain/noise overlay (very low opacity)
    noiseOverlay: {
      position: 'absolute',
      inset: 0,
      pointerEvents: 'none',
      backgroundImage: `radial-gradient(rgba(0,0,0,0.02) 1px, transparent 1px)`,
      backgroundSize: '3px 3px',
      opacity: 0.06,
      zIndex: 1
    },

    // decorative glow behind hero image
    heroGlow: {
      position: 'absolute',
      width: '640px',
      height: '640px',
      right: '6%',
      top: '6%',
      transform: 'translate(0, -10%)',
      background: 'radial-gradient(circle, rgba(212,163,115,0.25) 0%, rgba(212,163,115,0.08) 20%, transparent 60%)',
      filter: 'blur(50px)',
      zIndex: 0,
      borderRadius: '50%'
    },

    // Navigation (mostly unchanged but color/harmony improved)
    nav: {
      backgroundColor: 'transparent',
      padding: '1rem 1.5rem',
      zIndex: 3,
      position: 'relative'
    },
    navContainer: {
      maxWidth: '1200px',
      margin: '0 auto',
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center'
    },
    logo: {
      fontSize: '1.9rem',
      fontWeight: '700',
      color: '#F7EFE6',
      textShadow: '0 1px 0 rgba(0,0,0,0.15)'
    },

    // Hero
    hero: {
      padding: '4rem 1.25rem',
      minHeight: '70vh',
      display: 'flex',
      alignItems: 'center',
      position: 'relative',
      zIndex: 2,
    },
    heroContainer: {
      maxWidth: '1200px',
      margin: '0 auto',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'space-between',
      gap: '3rem',
      width: '100%',
      flexWrap: 'wrap'
    },
    heroContent: {
      flex: '1 1 480px',
      textAlign: 'left',
      maxWidth: '650px',
      zIndex: 2
    },
    heroImageContainer: {
      flex: '1 1 360px',
      display: 'flex',
      justifyContent: 'flex-end',
      alignItems: 'center',
      zIndex: 2,
      minWidth: '320px'
    },
    heroImage: {
      width: '100%',
      maxWidth: '420px',
      height: 'auto',
      borderRadius: '18px',
      boxShadow: '0 30px 60px rgba(24,18,14,0.35), inset 0 1px 0 rgba(255,255,255,0.03)',
      transform: 'translateY(0)',
      transition: 'transform 0.45s cubic-bezier(.2,.9,.2,1), box-shadow 0.35s ease',
      zIndex: 2
    },
    heroImageHover: {
      transform: 'translateY(-6px) scale(1.02)'
    },

    heroTitle: {
      fontSize: '3.2rem',
      fontWeight: '700',
      marginBottom: '1rem',
      lineHeight: '1.05',
      color: '#2e1f1a',
      fontFamily: "'Lora', serif",
      textShadow: '0 2px 0 rgba(255,255,255,0.02)'
    },
    heroText: {
      fontSize: '1.125rem',
      color: '#3a2b27',
      marginBottom: '2rem',
      opacity: 0.95,
      lineHeight: '1.7',
    },

    heroButtons: {
      display: 'flex',
      gap: '1rem',
      flexWrap: 'wrap'
    },
    btnPrimary: {
      textDecoration: 'none',
      background: 'linear-gradient(135deg, #664f46ff 0%, #694e4eff 25%, #4d271dff 50%, #523232ff 75%, #6a3e2cff 100%)',
      color: '#F7EFE6',
      padding: '0.9rem 1.75rem',
      borderRadius: '12px',
      border: '1px solid rgba(60,40,30,0.25)',
      boxShadow: '0 8px 20px rgba(59,47,44,0.18)',
      fontSize: '1rem',
      fontWeight: 700,
      cursor: 'pointer',
      transition: 'transform 0.24s ease, box-shadow 0.24s ease'
    },
    btnPrimaryHover: {
      transform: 'translateY(-3px)',
      boxShadow: '0 18px 40px rgba(59,47,44,0.22)'
    },
    btnSecondary: {
      textDecoration: 'none',
      background: 'linear-gradient(135deg, #664f46ff 0%, #694e4eff 25%, #4d271dff 50%, #523232ff 75%, #6a3e2cff 100%)',
      color: '#F7EFE6',
      padding: '0.9rem 1.75rem',
      borderRadius: '12px',
      border: '1px solid rgba(60,40,30,0.25)',
      boxShadow: '0 8px 20px rgba(59,47,44,0.18)',
      fontSize: '1rem',
      fontWeight: 700,
      cursor: 'pointer',
      transition: 'transform 0.24s ease, box-shadow 0.24s ease',
    },


    // How It Works
    howItWorks: {
      padding: '5rem 1.5rem',
      background: 'linear-gradient(135deg, #664f46ff 0%, #694e4eff 25%, #4d271dff 50%, #523232ff 75%, #6a3e2cff 100%)',
      zIndex: 2
    },
    container: {
      maxWidth: '1200px',
      margin: '0 auto'
    },
    sectionTitle: {
      fontSize: '2.2rem',
      fontWeight: '700',
      textAlign: 'center',
      marginBottom: '3rem',
      color: '#2e1f1a'
    },
    sectionTitleLight: {
      fontSize: '2.2rem',
      fontWeight: '700',
      textAlign: 'center',
      marginBottom: '3rem',
      color: '#F7EFE6',
      textShadow: '0 2px 4px rgba(0,0,0,0.3)'
    },
    steps: {
      display: 'grid',
      gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))',
      gap: '2rem'
    },
    step: {
      textAlign: 'center',
      padding: '1.5rem',
      borderRadius: '12px',
      background: 'linear-gradient(180deg, rgba(255,255,255,0.02), rgba(0,0,0,0.02))',
      boxShadow: '0 10px 30px rgba(45,34,30,0.08)',
      border: '1px solid rgba(16,10,8,0.04)',
      transform: 'translateX(100px)',
      opacity: 0,
      transition: 'all 0.8s cubic-bezier(0.25, 0.46, 0.45, 0.94)'
    },
    stepDark: {
      textAlign: 'center',
      padding: '1.5rem',
      borderRadius: '12px',
      background: 'linear-gradient(145deg, rgba(255,255,255,0.1), rgba(255,255,255,0.05))',
      boxShadow: '0 15px 35px rgba(0,0,0,0.3)',
      border: '1px solid rgba(255,255,255,0.1)',
      backdropFilter: 'blur(10px)',
      transform: 'translateX(100px)',
      opacity: 0,
      transition: 'all 1.5s cubic-bezier(0.25, 0.46, 0.45, 0.94)'
    },
    stepIcon: {
      backgroundColor: '#3b2f2f',
      width: '64px',
      height: '64px',
      borderRadius: '50%',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      margin: '0 auto 1rem',
      boxShadow: '0 6px 18px rgba(45,34,30,0.12)'
    },
    stepTitle: {
      fontSize: '1.125rem',
      fontWeight: '700',
      marginBottom: '0.5rem',
      color: '#3b2f2f'
    },
    stepTitleLight: {
      fontSize: '1.125rem',
      fontWeight: '700',
      marginBottom: '0.5rem',
      color: '#F7EFE6'
    },
    stepText: {
      color: '#4b3933',
      fontSize: '0.99rem',
      lineHeight: '1.6'
    },
    stepTextLight: {
      color: '#E0D5CC',
      fontSize: '0.99rem',
      lineHeight: '1.6'
    },

    // Features
    features: {
      padding: '4rem 1.5rem',
      zIndex: 2
    },
    featuresGrid: {
      display: 'grid',
      gridTemplateColumns: 'repeat(3, 1fr)',
      gap: '2rem',
      '@media (max-width: 768px)': {
        gridTemplateColumns: '1fr'
      }
    },
    featureCard: {
      padding: '1.5rem',
      borderRadius: '12px',
      background: 'linear-gradient(135deg, #664f46ff 0%, #694e4eff 25%, #4d271dff 50%, #523232ff 75%, #6a3e2cff 100%)',
      boxShadow: '0 15px 35px rgba(0,0,0,0.3)',
      border: '1px solid rgba(255,255,255,0.1)',
      backdropFilter: 'blur(10px)',
      transform: 'translateX(100px)',
      opacity: 0,
      transition: 'all 1.5s cubic-bezier(0.25, 0.46, 0.45, 0.94)'
    },
    featureTitle: {
      fontSize: '1.3rem',
